import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def setup(**kw):
    c = sqlite3.connect(":memory:", **kw)
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def state(c):
    return (balance(c, "a"), balance(c, "b"), c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0])


INITIAL = (100, 20, 0)

# Invalid transfers
for args in [("a", "a", 10), ("a", "x", 10), ("x", "b", 10), ("a", "b", 0), ("a", "b", -5),
             ("a", "b", True), ("a", "b", 1.0), ("a", "b", "10"), ("a", "b", 101), ("a", "b", None)]:
    c = setup(); p = Recorder()
    try:
        transfer(c, p, *args)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for {args}")
    assert state(c) == INITIAL, args
    assert p.events == [] and not c.in_transaction, args

# Exact balance is allowed; ledger row recorded once
c = setup(); p = Recorder()
transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1)
assert c.execute("SELECT * FROM ledger").fetchall() == [("a", "b", 100)]
assert p.events == [{"source": "a", "target": "b", "amount": 100}]


class FailingConnection:
    def __init__(self, inner, fail_on):
        self.inner, self.fail_on, self.count = inner, fail_on, 0

    def execute(self, sql, *a):
        if sql.lstrip().upper().startswith(("UPDATE", "INSERT")):
            self.count += 1
            if self.count == self.fail_on:
                raise sqlite3.OperationalError("boom")
        return self.inner.execute(sql, *a)

    def commit(self):
        if self.fail_on == "commit":
            raise sqlite3.OperationalError("commit boom")
        self.inner.commit()

    def rollback(self):
        self.inner.rollback()

    @property
    def in_transaction(self):
        return self.inner.in_transaction


for kw in [{}, {"isolation_level": None}]:
    for fail_on in [1, 2, 3, "commit"]:
        c = setup(**kw); p = Recorder()
        try:
            transfer(FailingConnection(c, fail_on), p, "a", "b", 10)
        except sqlite3.OperationalError:
            pass
        else:
            raise AssertionError("expected failure")
        assert state(c) == INITIAL, (kw, fail_on)
        assert p.events == [] and not c.in_transaction


class BadPublisher:
    def publish(self, event):
        raise RuntimeError("publish failed")


c = setup()
try:
    transfer(c, BadPublisher(), "a", "b", 10)
except RuntimeError:
    pass
else:
    raise AssertionError("publish failure must propagate")
assert state(c) == (90, 30, 1)
c.rollback()
assert state(c) == (90, 30, 1)

c = setup(isolation_level=None); p = Recorder()
transfer(c, p, "a", "b", 10)
assert state(c) == (90, 30, 1) and len(p.events) == 1
print("ok")
